const staticData = $getWorkflowStaticData('global');
const context = $('START CINNA PAGINATION').item.json;
const shopKey = context.shopKey;
const shopName = context.shopName;
const shopDomain = context.shopDomain;

let response = $json;
if (typeof response.data === 'string') {
  response = JSON.parse(response.data);
}

const products = response.data?.products?.edges || [];
const pageInfo = response.data?.products?.pageInfo || {};

const storageKey = `${shopKey}Minusbestand`;
if (!Array.isArray(staticData[storageKey])) {
  staticData[storageKey] = [];
}

for (const productEdge of products) {
  const product = productEdge.node || {};
  const variants = product.variants?.edges || [];

  for (const variantEdge of variants) {
    const variant = variantEdge.node || {};
    const bestand = Number(variant.inventoryQuantity ?? 0);

    if (bestand < 0) {
      staticData[storageKey].push({
        shop: shopName,
        productTitle: product.title || '',
        variantTitle: variant.title || '',
        sku: variant.sku || '',
        barcode: variant.barcode || '',
        inventoryQuantity: bestand,
        status: product.status || '',
        productUrl: `https://${shopDomain}/products/${product.handle || ''}`,
      });
    }
  }
}

staticData[shopKey].nextCursor = pageInfo.endCursor || null;
staticData[shopKey].hasNextPage = Boolean(pageInfo.hasNextPage);

return [{
  json: {
    shopKey,
    shopName,
    hasNextPage: staticData[shopKey].hasNextPage,
    nextCursor: staticData[shopKey].nextCursor,
    minusbestandCount: staticData[storageKey].length,
  },
}];

const staticData = $getWorkflowStaticData('global');
const shop = staticData.cinna;

return [{
  json: {
    shopKey: 'cinna',
    shopName: shop.shopName,
    shopDomain: shop.shopDomain,
    accessToken: shop.accessToken,
    cursor: shop.nextCursor || null,
  },
}];

const staticData = $getWorkflowStaticData('global');
const shop = staticData.leaf;

return [{
  json: {
    shopKey: 'leaf',
    shopName: shop.shopName,
    shopDomain: shop.shopDomain,
    accessToken: shop.accessToken,
    cursor: shop.nextCursor || null,
  },
}];

