const staticData = $getWorkflowStaticData('global');

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function buildTable(title, rows) {
  const sortedRows = [...rows].sort((a, b) => Number(a.inventoryQuantity) - Number(b.inventoryQuantity));

  if (sortedRows.length === 0) {
    return `<h2>${escapeHtml(title)}</h2><p>Keine Produkte mit Minusbestand gefunden.</p>`;
  }

  const trs = sortedRows.map(row => `
    <tr>
      <td>${escapeHtml(row.productTitle)}</td>
      <td>${escapeHtml(row.variantTitle)}</td>
      <td>${escapeHtml(row.sku)}</td>
      <td>${escapeHtml(row.barcode)}</td>
      <td style="text-align:right;"><strong>${escapeHtml(row.inventoryQuantity)}</strong></td>
      <td>${escapeHtml(row.status)}</td>
      <td><a href="${escapeHtml(row.productUrl)}">Produkt öffnen</a></td>
    </tr>
  `).join('');

  return `
    <h2>${escapeHtml(title)}</h2>
    <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px;">
      <thead>
        <tr style="background:#f2f2f2;">
          <th>Produkt</th>
          <th>Variante</th>
          <th>SKU</th>
          <th>Barcode/EAN</th>
          <th>Bestand</th>
          <th>Status</th>
          <th>Link</th>
        </tr>
      </thead>
      <tbody>${trs}</tbody>
    </table>
  `;
}

const report = staticData.report || {};
const cinnaRows = Array.isArray(staticData.cinnaMinusbestand) ? staticData.cinnaMinusbestand : [];
const leafRows = Array.isArray(staticData.leafMinusbestand) ? staticData.leafMinusbestand : [];
const timestamp = $now.setZone(report.timezone || 'Europe/Berlin').toFormat('dd.MM.yyyy HH:mm');

const html = `
  <p>Guten Morgen,</p>
  <p>hier ist der morgendliche Shopify-Minusbestand-Report vom ${timestamp} Uhr.</p>
  <p>Definition: Aufgeführt werden Varianten mit Bestand kleiner 0.</p>
  ${buildTable('CINNA - Produkte mit Minusbestand', cinnaRows)}
  <br>
  ${buildTable('LEAF - Produkte mit Minusbestand', leafRows)}
  <p>Liebe Grüße<br>${escapeHtml(report.titel || 'Shopify Minusbestand Report')} - Flow</p>
`;

return [{
  json: {
    titel: report.titel || 'Shopify Minusbestand Report',
    sendto: report.sendto || '',
    subject: `${report.titel || 'Shopify Minusbestand Report'} - ${$now.setZone(report.timezone || 'Europe/Berlin').toFormat('dd.MM.yyyy')}`,
    mailText: html,
    cinnaMinusbestandCount: cinnaRows.length,
    leafMinusbestandCount: leafRows.length,
    totalMinusbestandCount: cinnaRows.length + leafRows.length,
  },
}];

